bool hasPermission(int) { return true; }
void enforcePermission(int) {}
void logDenied(int) {}

void permissionCheckedOverride(int uid)
{
  if (!hasPermission(uid)) {
    logDenied(uid);
    return;
  }
  enforcePermission(uid);
}

void permissionCheckedOverrideVariant(int uid)
{
  if (!hasPermission(uid)) {
    logDenied(uid);
    return;
  }
  enforcePermission(uid);
}

void permissionCheckedShadow(int uid)
{
  if (!hasPermission(uid)) {
    logDenied(uid);
    return;
  }
  enforcePermission(uid);
}

void denyOnlyNoise(int uid)
{
  logDenied(uid);
}
